use crate::aap::caps::types::{FeedDocument, FetchFailure};
use crate::aap::caps::{http_client, state_rw};

const ALLOWED: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, or None if the URL is malformed or
/// uses anything we do not want to reason about (userinfo, other schemes).
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty() || authority.contains('@') {
        return None;
    }
    let host = match authority.rfind(':') {
        Some(i) => &authority[..i],
        None => authority,
    };
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received, under the shared key `last-input`.
        state_rw::put("last-input", &subscriptions.urls.join("\n"));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            // Out-of-allowlist requests trap at the boundary; report them as
            // data instead so one bad entry does not fail the tick.
            let allowed = host_of(&url)
                .map(|h| ALLOWED.contains(&h.as_str()))
                .unwrap_or(false);
            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host not permitted".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
